import React, { useState } from 'react';
import ResetPasswordModal from './ResetPasswordModal';

export default function TeacherDashboard({ userName, subject, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  
  // 🟢 Database එකෙන් එන "O/L - Mathematics" වගේ එකෙන් Grade එකයි Subject එකයි වෙන් කරගන්නවා
  const fullSubject = subject || 'O/L - Mathematics';
  const subjectParts = fullSubject.split(' - ');
  const teachingGrade = subjectParts.length > 1 ? subjectParts[0] : 'General';
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  const [isEditing, setIsEditing] = useState(false);
  const [profileData, setProfileData] = useState({ 
      name: userName || 'Teacher', 
      phone: '0701234567', 
      address: 'Mirigama, Sri Lanka' 
  });

  const [showResetModal, setShowResetModal] = useState(false);

  const handleProfileUpdate = () => {
      alert("✅ Profile details updated successfully!");
      setIsEditing(false);
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px' }}>
              <h1 style={{ margin: '0 0 10px 0', fontSize: '32px' }}>Welcome, {profileData.name}! 👋</h1>
              <p style={{ margin: 0, opacity: 0.9 }}>Content Management System is active. Manage your lessons and activities below.</p>
            </div>
            {/* 🟢 Grades පෙන්වන්න අලුතින් Card එකක් එකතු කළා */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '40px' }}>
              <DashboardCard title="Active Subject" count={teachingSubject} icon="📚" color="#eff6ff" textColor="#1d4ed8" />
              <DashboardCard title="Teaching Grades" count={teachingGrade} icon="🏫" color="#f5f3ff" textColor="#7c3aed" />
              <DashboardCard title="Uploaded Lessons" count="12" icon="📺" color="#f0fdf4" textColor="#15803d" />
              <DashboardCard title="Active Quizzes" count="05" icon="📝" color="#fefce8" textColor="#a16207" />
            </div>
          </>
        );

      case 'upload':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📤 Upload Lesson Materials</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', maxWidth: '600px' }}>
                <form style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                    <div>
                        <label style={labelStyle}>Lesson Title</label>
                        <input type="text" placeholder="e.g. Introduction to Algebra" style={inputStyle} />
                    </div>
                    <div>
                        <label style={labelStyle}>Grade Category</label>
                        <select style={inputStyle}>
                            <option>Grade 9</option>
                            <option>Grade 10</option>
                            <option>Grade 11</option>
                        </select>
                    </div>
                    <div>
                        <label style={labelStyle}>YouTube Video URL</label>
                        <input type="url" placeholder="https://youtube.com/watch?v=..." style={inputStyle} />
                    </div>
                    <div>
                        <label style={labelStyle}>PDF Handout Upload</label>
                        <input type="file" accept=".pdf" style={{...inputStyle, padding: '9px'}} />
                    </div>
                    <button type="button" style={{ padding: '12px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', marginTop: '10px' }}>+ Publish Lesson</button>
                </form>
            </div>
          </div>
        );

      case 'activities':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>🎮 Manage Interactive Activities</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
                <h3 style={{ marginTop: 0 }}>Create New Assessment</h3>
                <div style={{ display: 'flex', gap: '15px', marginTop: '15px' }}>
                    <button style={actionBtnStyle}>+ Create MCQ Quiz</button>
                    <button style={actionBtnStyle}>+ Create Matching Game</button>
                    <button style={actionBtnStyle}>+ Create Fill-in-the-blanks</button>
                </div>
            </div>
          </div>
        );

      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s', backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', maxWidth: '600px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '25px', borderBottom: '2px solid #f1f5f9', paddingBottom: '15px' }}>
                <h2 style={{ color: '#15803d', margin: 0 }}>👤 Teacher Profile</h2>
                {!isEditing ? <button onClick={() => setIsEditing(true)} style={editBtnStyle}>Edit Profile</button> : <button onClick={handleProfileUpdate} style={saveBtnStyle}>Save Changes</button>}
            </div>
            
            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
              <div><label style={labelStyle}>Full Name</label><input type="text" value={profileData.name} onChange={(e) => setProfileData({...profileData, name: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
              <div style={{ display: 'flex', gap: '20px' }}>
                  <div style={{ flex: 1 }}><label style={labelStyle}>Teaching Subject</label><input type="text" value={fullSubject} disabled style={inputStyleProfile(false)} /></div>
                  <div style={{ flex: 1 }}><label style={labelStyle}>Contact Number</label><input type="text" value={profileData.phone} onChange={(e) => setProfileData({...profileData, phone: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
              </div>
              <div><label style={labelStyle}>Residence Address</label><input type="text" value={profileData.address} onChange={(e) => setProfileData({...profileData, address: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
            </div>

            <div style={{ marginTop: '35px', paddingTop: '25px', borderTop: '2px solid #f1f5f9' }}>
                <h3 style={{ color: '#1e293b', margin: '0 0 10px 0' }}>🔒 Security & Password</h3>
                <p style={{ color: '#64748b', fontSize: '14px', marginBottom: '15px' }}>Keep your account secure by updating your password regularly.</p>
                <button onClick={() => setShowResetModal(true)} style={{ padding: '10px 20px', backgroundColor: '#e2e8f0', color: '#334155', border: '1px solid #cbd5e1', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>🔑 Change Password</button>
            </div>
          </div>
        );

      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f4f7f6', fontFamily: 'sans-serif' }}>
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '25px 0', display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '0 15px' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'upload'} onClick={() => setActiveTab('upload')} icon="📤" text="Content Manager" />
          <SidebarBtn active={activeTab === 'activities'} onClick={() => setActiveTab('activities')} icon="🎮" text="Manage Activities" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="My Profile" />
        </div>
        <div style={{ marginTop: 'auto', padding: '0 15px' }}><button onClick={handleLogout} style={logoutBtnStyle}>Logout</button></div>
      </div>
      
      <div style={{ flex: 1, padding: '40px 50px' }}>{renderContent()}</div>

      {showResetModal && <ResetPasswordModal userName={profileData.name} role="teacher" setShowResetModal={setShowResetModal} />}
    </div>
  );
}

// Custom UI Components
const SidebarBtn = ({ active, onClick, icon, text }) => (<button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '15px', display: 'flex', alignItems: 'center', gap: '12px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }}><span style={{ fontSize: '18px' }}>{icon}</span> {text}</button>);
const DashboardCard = ({ title, count, icon, color, textColor }) => (<div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `5px solid ${textColor}` }}><div><p style={{ margin: '0 0 5px 0', color: '#64748b', fontSize: '14px', fontWeight: 'bold' }}>{title}</p><h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px' }}>{count}</h2></div><div style={{ width: '60px', height: '60px', borderRadius: '50%', backgroundColor: color, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '28px' }}>{icon}</div></div>);

// Styles
const labelStyle = { display: 'block', marginBottom: '8px', color: '#475569', fontSize: '14px', fontWeight: 'bold' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', color: '#1e293b' };
const inputStyleProfile = (isEditing) => ({ width: '100%', padding: '12px', borderRadius: '8px', border: isEditing ? '1px solid #3b82f6' : '1px solid #cbd5e1', backgroundColor: isEditing ? 'white' : '#f8fafc', outline: 'none', boxSizing: 'border-box', color: '#1e293b' });
const actionBtnStyle = { flex: 1, padding: '12px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' };
const logoutBtnStyle = { width: '100%', padding: '12px', backgroundColor: '#ef4444', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' };
const editBtnStyle = { padding: '8px 16px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' };
const saveBtnStyle = { padding: '8px 16px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' };
